function MiniField({ label, children }) {
  return (
    <div>
      <div style={{ fontSize: 10, color: "#9b9993", marginBottom: 3, textTransform: "uppercase", letterSpacing: 0.5, fontWeight: 700 }}>{label}</div>
      {children}
    </div>
  );
}

